 public static func layoutWidth(for size:CGFloat,windowCount:Int=2)->CGFloat{LaurelProfile.select(size,windowCount:windowCount).width * (size>22 ? size/22:1)}
 public static func layoutHeight(for size:CGFloat,windowCount:Int=2)->CGFloat{LaurelProfile.select(size,windowCount:windowCount).height * (size>22 ? size/22:1)}
 private var width:CGFloat{p.width*factor}
 private var height:CGFloat{p.height*factor}
 private var center:CGPoint {
  let step=factor/density
  let origin=zoom == 1 ? pixelOrigin:.zero
  return CGPoint(x:((width/2+origin.x)/step).rounded()*step-origin.x,y:((height/2+origin.y)/step).rounded()*step-origin.y)
 }
 private var motion:Animation?{reduceMotion ? nil:.smooth(duration:duration)}
 private var statusFocused:Bool{state.health != .live}
 private var showPace:Bool {
  guard !statusFocused,state.pace != .normal else{return false}
  if let event=state.paceEventAt{return expiredEvent != event && now >= event && now.timeIntervalSince(event)<GaugeModifierMotion.noticeDuration(duration)}
  return automaticNotice
 }
 private var paceName:String{state.pace == .fast ? "hare.fill":state.pace == .slow ? "tortoise.fill":"flame.fill"}
 private var problemName:String? {
  switch state.health {
   case .outage:return "bolt.horizontal.fill"
   case .unknown:return "questionmark"
   case .authentication:return "key.fill"
   case .offline,.disabled:return "circle.slash"
   case .paused:return "pause.fill"
   case .stale:return "clock"
   case .live:return nil
  }
 }
 private func name(_ role:String,_ suffix:String)->String{"compute.laurel.\(windows.count == 2 ? "":"w\(windows.count).")p\(Int(p.size)).\(role).\(suffix)"}
 private func arc(_ role:String,_ count:Int=0,_ value:Double=1,_ left:Bool=false)->some View {
  let n=name(role,count==0 ? "window":"reset\(min(24,max(1,count)))")
  let source=Self.source[n]![wi],m=Self.native[n]![wi]
  let x=(source.centerX-m[0]*p.size)*factor
  let y=(source.centerY-m[1]*p.size)*factor
  return Image(n,variableValue:value).symbolVariableValueMode(.color)
   .font(.system(size:p.size*factor,weight:weight)).imageScale(.small)
   .symbolRenderingMode(.hierarchical)
   .scaleEffect(x:left ? -1:1,y:1)
   .position(x:center.x+(left ? -x:x),y:center.y+y)
   .frame(width:width,height:height)
 }
 private func nativeUsage(_ role:String,_ value:Double)->some View {
  // The native Draw path owns both caps. Its outline and advance match the
  // corresponding window asset, so it shares that asset's measured placement.
  let window=name(role,"window")
  let source=Self.source[window]![wi],m=Self.native[window]![wi]
  let x=(source.centerX-m[0]*p.size)*factor
  let y=(source.centerY-m[1]*p.size)*factor
  return LaurelVariableUsageImage(name:name(role,"usage"),value:value)
   .font(.system(size:p.size*factor,weight:weight)).imageScale(.small)
   .symbolRenderingMode(.hierarchical)
   .position(x:center.x+x,y:center.y+y)
   .frame(width:width,height:height)
 }
 @ViewBuilder private func usage(_ role:String,_ ring:LaurelProfile.Ring,_ value:Double?) -> some View {
  if let value,value.isFinite {
   let remaining=1-min(1,max(0,value))
   nativeUsage(role,remaining).animation(motion,value:value)
  }else{
   // Unknown retains the system dashed glyph and its separate calibration.
   let spec=GaugeCalibration.Ring(glyph:ring.glyph,diameter:(2*ring.radius+ring.stroke)*factor)
   NativeGaugeLayer(value:nil,spec:spec,size:width,center:CGPoint(x:width/2,y:width/2))
    .rotationEffect(.degrees(90)).frame(width:width,height:height)
    .mask{arc(role).foregroundStyle(.white)}
    .scaleEffect(x:1,y:-1,anchor:UnitPoint(x:0.5,y:center.y/height))
  }
 }
 private func countdown(_ role:String,_ cycle:ResetCountdown)->some View {
  let v=cycle.value(at:now)
  return ZStack {
   arc(role,cycle.units,1,true).opacity(0.24)
   arc(role,cycle.units,v ?? 1,true).opacity(v == nil ? 0.42:1)
    .contentTransition(.symbolEffect(.automatic))
    .symbolEffectsRemoved(reduceMotion).animation(motion,value:v)
  }.foregroundStyle(statusFocused ? AnyShapeStyle(.tertiary):AnyShapeStyle(.secondary))
 }
 private var provider:some View {
  let product=state.productID
  let service=ServiceIdentity.find(product)
  let n=service?.symbol(p.size) ?? "provider.\(product).compact"
  let pw=service?.existing == false || ["codex","kimi"].contains(product) ? wi:[2,2,3,3,3,4,4,5,5][wi]
  let ink=service?.nativeInk(p.size,pw) ?? Self.providerInk[n]?[pw] ?? [0,0,0.70459,0.70459]
  let inkWidth=service?.targetInk(p.size) ?? p.logo
  let optical=service?.opticalOffset ?? .zero
  let font=inkWidth/max(ink[2],ink[3])*factor
  let inkX=center.x+optical.width*factor,inkY=center.y+optical.height*factor
  // Align the measured outer ink bounds, not the invisible font advance.
  // Preserve the logical pixel phase in native magnified inspection.
  let step=factor/density,origin=zoom == 1 ? pixelOrigin:CGPoint.zero
  let x=service?.hasMicroGrid == true ? ((inkX-ink[2]*font/2+origin.x)/step).rounded()*step-origin.x+ink[2]*font/2:inkX
  let y=service?.hasMicroGrid == true ? ((inkY-ink[3]*font/2+origin.y)/step).rounded()*step-origin.y+ink[3]*font/2:inkY
  return Image(n).font(.system(size:font,weight:GaugeCalibration.Glyph.weights[pw])).imageScale(.small)
   .symbolRenderingMode(statusFocused ? .palette:.hierarchical)
   .foregroundStyle(HierarchicalShapeStyle.primary,HierarchicalShapeStyle.secondary,statusFocused ? AnyShapeStyle(.secondary):AnyShapeStyle(.tertiary))
   .contentTransition(.symbolEffect(.replace)).symbolEffectsRemoved(reduceMotion)
   .position(x:x-ink[0]*font,y:y-ink[1]*font)
 }
 private var notice:some View {
  let animal=state.pace == .fast || state.pace == .slow
  // Native animals face right. Turning the glyph a quarter-turn makes them
  // face up and gives their long axis the full vertical countdown slot.
  let horizontal=state.pace == .fast ? 1.185:state.pace == .slow ? 1.2875:0.6675
  let vertical=state.pace == .fast ? 0.8525:state.pace == .slow ? 0.6475:0.855
  let targetHeight=p.size==18 ? 11.0:p.size==20 ? 12.0:13.0
  let slotWidth=(p.width-p.logo-2)/2-1.0
  let nativeHeight=animal ? horizontal:vertical
  let nativeWidth=animal ? vertical:horizontal
  let font=min(targetHeight/nativeHeight,slotWidth/nativeWidth)
  return NativeModifierSymbol(name:paceName,font:font*factor,weight:.semibold,
    angle:animal ? -90:0,replay:state.paceEventAt)
   .position(x:(slotWidth/2+0.25)*factor,y:center.y)

 }
 private var spokenSummary:String {
  if !state.accessibilityDescription.isEmpty{return state.accessibilityDescription}
  return "\(state.productName). \(state.health.rawValue). \(state.usageSummary(at:now)). \(state.pace.rawValue) pace."
 }
 private var problemNames:[String]{problemName.map{[$0]} ?? []}
 private func modifierTransition(_ name:String)->AnyTransition {
  GaugeModifierMotion.transition(name,scale:factor,vertical:true,duration:duration,reduceMotion:reduceMotion)
 }
 private func problem(_ name:String)->some View {
  let optical=GaugeStatusOptics.spec(name,size:p.size,weight:weight,wide:true)
  return NativeModifierSymbol(name:name,font:(optical?.font ?? (name == "key.fill" ? 19:18))*factor,weight:optical?.weight ?? .semibold,
   angle:name == "circle.slash" ? -17:0,replay:state.healthEventAt)
   .position(center)
 }
 private func problemGap(_ name:String,logo:Bool=false)->CGSize {
  if logo{return CGSize(width:0.25*factor,height:0.25*factor)}
  // Narrow punctuation needs a narrow horizontal moat, particularly at 18 pt.
  let x:CGFloat=["exclamationmark","questionmark"].contains(name) ? (p.size==18 ? 0.65:0.55):1.0
  return CGSize(width:x*factor,height:(["exclamationmark","questionmark"].contains(name) ? 1.0:1.1)*factor)
 }
 private func statusClearance(logo:Bool=false)->some View {
  ZStack {
   Color.white
   ForEach(problemNames,id:\.self){name in
    NativeSymbolClearance(gap:problemGap(name,logo:logo)){problem(name)}
     .id(name+"-"+String(state.healthEventAt?.timeIntervalSince1970 ?? 0))
     .transition(modifierTransition(name)).blendMode(.darken)
   }
  }.compositingGroup().luminanceToAlpha()
 }
 public var body:some View {
  ZStack {
   ZStack {
     ForEach(Array(windows.enumerated()),id:\.element.id){index,window in
      usage(roles[index],pair.ring(roles[index]),window.usedFraction)
       .foregroundStyle(statusFocused ? AnyShapeStyle(.secondary):AnyShapeStyle(.primary))
     }
     if showPace {notice.id(paceName+"-"+String(state.paceEventAt?.timeIntervalSince1970 ?? 0)).transition(modifierTransition(paceName))}else{
      ForEach(Array(windows.enumerated()),id:\.element.id){index,window in
       if window.recovery != .none,let cycle=window.countdown {
        countdown(roles[index],cycle).transition(.opacity)
       }
      }
     }
   }
    .mask(statusClearance())
   if !isolated {provider.mask(statusClearance(logo:true))}
   ForEach(problemNames,id:\.self){name in
    problem(name).foregroundStyle(.primary).id(name+"-"+String(state.healthEventAt?.timeIntervalSince1970 ?? 0))
     .transition(modifierTransition(name))
   }
  }.frame(width:width,height:height)
   .onGeometryChange(for:CGPoint.self){$0.frame(in:.global).origin} action:{pixelOrigin=$0}
   .animation(motion,value:state).animation(motion,value:showPace)
   .task(id:"\(state.pace.rawValue)-\(state.paceEventAt?.timeIntervalSince1970 ?? 0)-\(duration)") {
    automaticNotice=false
    guard state.pace != .normal else{return}
    if state.paceEventAt == nil{automaticNotice=true}
    let remaining=state.paceEventAt.map{max(0,GaugeModifierMotion.noticeDuration(duration)-Date.now.timeIntervalSince($0))} ?? GaugeModifierMotion.noticeDuration(duration)
    do{try await Task.sleep(for:.seconds(remaining))}catch{return}
    automaticNotice=false;expiredEvent=state.paceEventAt
   }
   .accessibilityElement(children:.ignore)
   .accessibilityLabel(spokenSummary)
 }
}

/// Interpolate the native variable value through SwiftUI transactions.
private struct LaurelVariableUsageImage:View,Animatable {
 var name:String
 nonisolated var value:Double
 nonisolated var animatableData:Double {
  get{value}
  set{value=newValue}
 }
 var body:some View {
  Image(name,variableValue:min(1,max(0,value))).symbolVariableValueMode(.draw)
 }
}
